<script setup>
import {onBeforeUnmount,onMounted,reactive,ref} from 'vue';
const props=defineProps({mode:String,indexUrl:String,createUrl:String,storeUrl:String,updateUrl:String,csrf:String,payload:String,errors:String,old:String});
function parse(v){try{return JSON.parse(v||'{}')}catch{return {}}}
const payload=parse(props.payload),errors=parse(props.errors),old=parse(props.old),blog=payload.blog||{};
const state=reactive({rows:[],pagination:{},filters:{search:new URLSearchParams(location.search).get('search')||'',status:new URLSearchParams(location.search).get('status')||''},form:{title:old.title??blog.title??'',excerpt:old.excerpt??blog.excerpt??'',content:old.content??blog.content??'',status:old.status??blog.status??'draft',published_at:old.published_at??blog.published_at??''},loading:false,error:''});
const preview=ref(payload.image_url||'');let abort;
async function load(url=props.indexUrl,push=false){abort?.abort();abort=new AbortController();state.loading=true;state.error='';try{const response=await fetch(url,{credentials:'same-origin',signal:abort.signal,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const d=await response.json();if(!response.ok)throw new Error(d.message||'Failed to load blog posts');state.rows=d.blogs||[];state.pagination=d.pagination||{};state.filters={search:'',status:'',...(d.filters||{})};if(push)history.pushState({},'',url)}catch(e){if(e.name!=='AbortError')state.error=e.message}finally{state.loading=false}}
function filteredUrl(){const url=new URL(props.indexUrl,location.origin);Object.entries(state.filters).forEach(([k,v])=>v&&url.searchParams.set(k,v));return url.href}
function apply(){load(filteredUrl(),true)}function reset(){state.filters={search:'',status:''};apply()}function page(l){l.url&&load(l.url,true)}
function imageChanged(event){const file=event.target.files?.[0];if(file)preview.value=URL.createObjectURL(file)}
async function remove(row){let confirmed;if(window.Swal){const result=await window.Swal.fire({title:'Delete Blog?',text:`"${row.title}" will be permanently deleted.`,icon:'warning',showCancelButton:true,confirmButtonText:'Delete',cancelButtonText:'Cancel'});confirmed=result.isConfirmed}else confirmed=confirm(`Delete "${row.title}"?`);if(!confirmed)return;const body=new FormData();body.append('_method','DELETE');try{const response=await fetch(row.delete_url,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf,'X-Requested-With':'XMLHttpRequest'},body});const d=await response.json();if(!response.ok||!d.success)throw new Error(d.message||'Failed to delete blog');await load(location.href);if(window.Swal)window.Swal.fire({icon:'success',title:'Deleted',text:d.message,timer:1200,showConfirmButton:false})}catch(e){state.error=e.message}}
function pop(){load(location.href)}
onMounted(()=>{if(props.mode==='index')load(props.indexUrl+location.search);window.addEventListener('popstate',pop)});onBeforeUnmount(()=>{abort?.abort();window.removeEventListener('popstate',pop)});
</script>
<template>
<div class="dashboard-section blogs-page" v-if="mode==='index'">
<div class="dashboard-panel blogs-header-panel"><div class="blogs-header-content"><div><h5>Blogs</h5><p>Manage your blog posts and publications</p></div><a :href="createUrl" class="blogs-add-btn"><i class="bi bi-plus-lg"></i><span>Add Blog</span></a></div></div>
<div v-if="state.error" class="blogs-alert"><i class="bi bi-exclamation-circle-fill"></i><span>{{state.error}}</span><button class="blogs-alert-close" @click="load()">Retry</button></div>
<div class="dashboard-panel blogs-filter-panel"><form @submit.prevent="apply"><div class="blogs-filter-row"><div class="blogs-search"><label for="blog-search">Search</label><div class="blogs-search-group"><i class="bi bi-search"></i><input id="blog-search" v-model="state.filters.search" placeholder="Search blog posts..."></div></div><div class="blogs-status-filter"><label for="blog-status">Status</label><select id="blog-status" v-model="state.filters.status"><option value="">All Statuses</option><option value="published">Published</option><option value="draft">Draft</option></select></div><div class="blogs-filter-actions"><button class="blogs-search-btn"><i class="bi bi-search"></i> Search</button><button v-if="state.filters.search||state.filters.status" type="button" class="blogs-reset-btn" title="Reset filters" @click="reset"><i class="bi bi-arrow-counterclockwise"></i></button></div></div></form></div>
<div class="dashboard-panel blogs-table-panel"><div class="blogs-table-wrapper"><table class="blogs-table"><thead><tr><th class="blog-col-id">#</th><th class="blog-col-image">Image</th><th>Blog</th><th>Author</th><th>Status</th><th>Published</th><th>Actions</th></tr></thead><tbody><tr v-if="state.loading"><td colspan="7" class="text-center py-4">Loading blog posts…</td></tr><tr v-for="row in state.rows" v-else :key="row.id"><td>#{{row.id}}</td><td><img v-if="row.image_url" :src="row.image_url" :alt="row.title" class="blog-image"><div v-else class="blog-image-placeholder"><i class="bi bi-image"></i></div></td><td><div class="blog-info"><div class="blog-name">{{row.title}}</div><div class="blog-excerpt">{{row.excerpt}}</div></div></td><td>{{row.author||'—'}}</td><td><span class="blog-status" :class="'blog-status-'+row.status"><span>{{row.status}}</span></span></td><td><div v-if="row.published_at" class="blog-date">{{row.published_at}}</div><span v-else class="blog-no-date">—</span></td><td><div class="blog-actions"><a :href="row.edit_url" class="blog-edit-btn" title="Edit Blog"><i class="bi bi-pencil"></i></a><button type="button" class="blog-delete-btn" title="Delete Blog" @click="remove(row)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="!state.loading&&!state.rows.length"><td colspan="7"><div class="blogs-empty"><div class="blogs-empty-icon"><i class="bi bi-journal-text"></i></div><h6>No Blog Posts Found</h6><p>There are no blog posts matching your search.</p><a :href="createUrl" class="blogs-add-btn"><i class="bi bi-plus-lg"></i> Add Blog</a></div></td></tr></tbody></table></div><div v-if="state.pagination.total>10" class="blogs-pagination"><span>Showing {{state.pagination.first_item}} to {{state.pagination.last_item}} of {{state.pagination.total}}</span><nav><button v-for="(link,i) in state.pagination.links" :key="i" class="page-link" :disabled="!link.url" :class="{active:link.active}" @click="page(link)" v-html="link.label"></button></nav></div></div>
</div>
<div v-else class="dashboard-section blogs-page">
<div class="dashboard-panel blogs-header-panel"><div class="blogs-header-content"><div><h5>{{mode==='create'?'Create Blog':'Edit Blog'}}</h5><p>Manage your blog post publication details</p></div><a :href="indexUrl" class="blogs-reset-btn"><i class="bi bi-arrow-left"></i> Back to Blogs</a></div></div>
<div class="dashboard-panel blog-form-panel p-4"><div v-if="Object.keys(errors).length" class="alert alert-danger"><strong>Please fix these errors:</strong><ul class="mb-0"><li v-for="(items,key) in errors" :key="key">{{items[0]}}</li></ul></div><form :action="mode==='create'?storeUrl:updateUrl" method="POST" enctype="multipart/form-data"><input type="hidden" name="_token" :value="csrf"><input v-if="mode==='edit'" type="hidden" name="_method" value="PUT">
<div class="blog-form-group blog-form-full mb-3"><label for="title">Title</label><input id="title" v-model="state.form.title" type="text" name="title" class="form-control" maxlength="255" required><small v-if="errors.title" class="text-danger">{{errors.title[0]}}</small></div>
<div class="blog-form-group blog-form-full mb-3"><label for="excerpt">Excerpt</label><textarea id="excerpt" v-model="state.form.excerpt" name="excerpt" class="form-control" rows="3" maxlength="1000"></textarea><small v-if="errors.excerpt" class="text-danger">{{errors.excerpt[0]}}</small></div>
<div class="blog-form-group blog-form-full mb-3"><label for="content">Content</label><textarea id="content" v-model="state.form.content" name="content" class="form-control" rows="12" required></textarea><small v-if="errors.content" class="text-danger">{{errors.content[0]}}</small></div>
<div class="blog-form-grid row g-3"><div class="blog-form-group col-md-6"><label for="status">Status</label><select id="status" v-model="state.form.status" name="status" class="form-select" required><option value="draft">Draft</option><option value="published">Published</option></select></div><div class="blog-form-group col-md-6"><label for="published_at">Published at</label><input id="published_at" v-model="state.form.published_at" type="datetime-local" name="published_at" class="form-control"></div></div>
<div class="blog-form-group mt-3"><label for="image">Image</label><input id="image" type="file" name="image" accept="image/jpeg,image/png,image/webp" class="form-control" @change="imageChanged"><img v-if="preview" :src="preview" class="mt-3" style="max-width:240px;max-height:180px;object-fit:cover" alt="Blog image preview"></div>
<div class="d-flex justify-content-end gap-2 mt-4"><a :href="indexUrl" class="blogs-reset-btn">Cancel</a><button class="blogs-add-btn" type="submit">{{mode==='create'?'Create Blog':'Save Changes'}}</button></div></form></div></div>
</template>
